/**
 * Ported from binectics-mobile src/guided/coach/types.ts (feat/simplify-guided-start, mobile #299).
 * Keep the behaviour identical to the mobile file; change both together.
 */
/**
 * Coach line bank types. A line is content, not behaviour: the engine decides
 * WHEN something is said, the selector picks WHICH line, the bank holds the
 * words. Lines never contain a number the timer owns (counts, set numbers, rest
 * seconds): those are always generated by code so a line cannot disagree with
 * the clock. The one exception is `bakedSeconds`, a line that is only offered
 * at exactly that many seconds left.
 */
export type Persona = 'lagos-strength';

export type Moment =
  | 'sessionStart'
  | 'countdownLead'
  | 'midSet'
  | 'lastReps'
  | 'setComplete'
  | 'rest'
  | 'form'
  | 'easeOff'
  | 'sessionComplete'
  | 'comeback';

export type LineTag =
  /** Fine to hear many times in one session. */
  | 'loop-safe'
  /** A line that lands once: at most once per session and once per 5 sessions. */
  | 'once'
  /** Spoken with a pause between sentences (punctuation only, no SSML). */
  | 'spoken-slow'
  /** Carries a local word; needs a `plain` twin and is shown only when "Local flavour" is on. */
  | 'local'
  /** Safety copy: only played from the ease-off button or after a long mid-set pause. */
  | 'safety';

export interface CoachLine {
  /** Stable id (recorded audio will use it). Append only: never renumber. */
  id: string;
  moment: Moment;
  text: string;
  tags: LineTag[];
  /** The same line without the local word. Required for `local` lines. */
  plain?: string;
  /** The line states this many seconds left; offered only when exactly that many remain. */
  bakedSeconds?: number;
  /** The line states which set it is ("That's one down"); offered only for exactly that set number. */
  bakedSet?: number;
  /** Rep language ("One more", "Last one"): never offered on a timed set (a hold, interval or cardio block). */
  repOnly?: boolean;
  /** The line repeats something the plain cue already says, so it is skipped when that cue is in the same utterance. */
  restates?: 'set' | 'rest';
}

export interface PickedLine {
  id: string;
  moment: Moment;
  /** Final spoken text: local/plain resolved, slow pauses applied. */
  text: string;
  /** The line itself says the seconds left, so the caller must not add "Ten seconds left." */
  statesSeconds: boolean;
}
